<template>
  <section class="wound-shell"><header><div><small>SKIN INTEGRITY</small><h2>Wound management</h2><p>Active wounds, measurements, photos and treatment status.</p></div><v-btn v-if="!readOnly" x-small depressed color="#0f766e" dark @click="$emit('open-wound')"><v-icon x-small left>mdi-bandage</v-icon>New wound</v-btn></header>
    <div class="metrics"><span><b>{{ wounds.length }}</b> total</span><span><b>{{ activeCount }}</b> active</span><span><b>{{ worseningCount }}</b> worsening</span><span><b>{{ photoCount }}</b> photos</span></div>
    <div v-if="wounds.length" class="wound-table"><div class="wound-row heading"><span>Wound / location</span><span>Status</span><span>Last measurement</span><span>Last assessment</span><span></span></div><div v-for="wound in wounds" :key="wound.id" class="wound-row"><span><strong>{{ wound.woundType||'Wound' }}</strong><small>{{ wound.anatomicalLocation||'Location not documented' }}</small></span><em :class="statusClass(wound.status)">{{ wound.status||'active' }}</em><span>{{ measurement(wound) }}</span><span>{{ lastDate(wound) }}</span><v-btn x-small text color="#0f766e" @click="$emit('open-wound',wound)">{{ readOnly?'Review':'Assess' }}</v-btn></div></div>
    <div v-else class="empty"><v-icon size="42" color="#94a3b8">mdi-bandage</v-icon><strong>No wound documented</strong><span>Place a wound marker on the Avatar or document a new wound here.</span></div>
  </section>
</template>
<script>
export default{name:'Patient360WoundManagementTab',props:{wounds:{type:Array,default:()=>[]},assessments:{type:Object,default:()=>({})},readOnly:Boolean},computed:{activeCount(){return this.wounds.filter(x=>!/healed|closed|resolved/i.test(x.status||'')).length},worseningCount(){return this.wounds.filter(x=>/worsen/i.test(x.status||'')).length},photoCount(){return Object.values(this.assessments).reduce((n,list)=>n+(list||[]).reduce((m,a)=>m+(a.photos||[]).length,0),0)}},methods:{latest(w){const list=this.assessments[w.id]||[];return [...list].sort((a,b)=>new Date(b.recordedAt||b.createdAt)-new Date(a.recordedAt||a.createdAt))[0]||{}},measurement(w){const a=this.latest(w);return [a.lengthCm,a.widthCm,a.depthCm].every(v=>v!==undefined&&v!==null)?`${a.lengthCm} × ${a.widthCm} × ${a.depthCm} cm`:'Not measured'},lastDate(w){const a=this.latest(w);const d=a.recordedAt||a.createdAt;return d?new Date(d).toLocaleString():'No assessment'},statusClass(v){return /worsen/i.test(v)?'danger':/heal|closed|resolved/i.test(v)?'good':'warning'}}}
</script>
<style scoped>
.wound-shell{padding:14px;background:#f8fbfb;min-height:100%}.wound-shell>header{display:flex;justify-content:space-between;align-items:center;border-bottom:2px solid #0f766e;padding-bottom:10px}.wound-shell small{font-weight:900;color:#64748b}.wound-shell h2{font-size:18px;margin:2px 0}.wound-shell p{margin:0;font-size:12px}.metrics{display:flex;gap:28px;padding:10px 0;font-size:12px}.metrics b{font-size:17px;color:#0f766e}.wound-table{border:1px solid #cbd5e1;background:white}.wound-row{display:grid;grid-template-columns:1.3fr .7fr 1fr 1fr 70px;gap:8px;align-items:center;padding:8px 10px;border-bottom:1px solid #e2e8f0;font-size:12px}.wound-row.heading{background:#e8f2f1;font-weight:900}.wound-row>span:first-child{display:flex;flex-direction:column}.wound-row small{color:#64748b}.wound-row em{font-style:normal;font-weight:900}.good{color:#047857}.warning{color:#b45309}.danger{color:#be123c}.empty{min-height:260px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:7px;color:#64748b}@media(max-width:800px){.wound-row{grid-template-columns:1fr 1fr}.wound-row.heading{display:none}}
</style>
